using HouyiDb;
using Xunit;

namespace HouyiDb.Tests;

public class StableIdTests
{
    /// <summary>
    /// stable_id 五方对拍：期望值由 Python SDK（hashlib.blake2b(digest_size=8)）
    /// 生成，与 TS/Go/Rust SDK、服务端网关同算法。跨语言一致是 delete 重放的前提。
    /// EN: stable_id cross-check across five parties: the expected values are
    /// generated by the Python SDK (hashlib.blake2b(digest_size=8)); the same
    /// algorithm as the TS/Go/Rust SDKs and the server gateway. Cross-language
    /// agreement is what makes delete replay possible.
    /// </summary>
    public static IEnumerable<object[]> GoldenVectors => new[]
    {
        new object[] { "", 7252660547403494068UL },
        new object[] { "hello", 2861735919082615933UL },
        new object[] { "node-42", 6694704320175634731UL },
        new object[] { "苹果香蕉", 4490440666094115033UL },
        new object[] { "doc-1", 6265767295393789249UL },
        new object[] { "a/b?c#d", 4199517732852746375UL },
    };

    [Theory]
    [MemberData(nameof(GoldenVectors))]
    public void MatchesPythonSdk(string text, ulong want) =>
        Assert.Equal(want, StableId.Of(text));

    [Fact]
    public void DeterministicAndPositiveHalf()
    {
        var a = StableId.Of("same-input");
        Assert.Equal(a, StableId.Of("same-input"));
        Assert.True(a <= (1UL << 63) - 1);
    }
}
